<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('patients.php');$page_title='Master Pasien';$page_subtitle=is_role('registration')?'Patient master data untuk front office.':'Patient identity dan demographic data untuk kebutuhan layanan Anda.';$rows=$pdo->query('SELECT id,mrn,name,gender,birth_date,blood_type,phone,insurance FROM patients ORDER BY name')->fetchAll();include __DIR__.'/includes/header.php';?>
